import importlib


class remote(object):
    """
    Robot keywords-interface for python ute_ue package
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __new__(cls, filename, class_to_load_name, *args, **kwargs):
        module = importlib.import_module('crt_tests.crt_android.remote.resources' + filename)
        klass = getattr(module, class_to_load_name)
        implementation = klass(*args, **kwargs)
        return implementation

    def __init__(self, *args, **kwargs):
        raise Exception("This init should be never invoke.")
